#!/usr/bin/env bash
# Copies the frontend files from the Rust repo (once-campfire-rust) into this directory.
# Run from any directory: third_party/rails-assets/refresh.sh [path-to-rust-repo]
# The script then writes MANIFEST.md (source path and SHA-256 of each file).
set -euo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
RUST="${1:-$HERE/../../../../once-campfire-rust}"
RUST="$(cd "$RUST" && pwd)"
REF="$RUST/reference"
CRATE="$RUST/crates/assets"

cd "$HERE"
rm -rf reference vendor overrides LOAD_PATH
mkdir -p reference/app reference/config/initializers

for d in app/assets/images app/assets/sounds app/assets/stylesheets app/javascript vendor/javascript public; do
  mkdir -p "reference/$d"
  cp -R "$REF/$d/." "reference/$d/"
done
cp "$REF/config/importmap.rb" reference/config/importmap.rb
cp "$REF/config/initializers/assets.rb" reference/config/initializers/assets.rb
cp "$REF/MIT-LICENSE" reference/MIT-LICENSE

cp -R "$CRATE/vendor" vendor
mv vendor/MANIFEST.md vendor/GEMS.md
mv vendor/LOAD_PATH LOAD_PATH
cp -R "$CRATE/overrides" overrides

# Remove build products and editor files, if any.
find . -name .DS_Store -delete

# MANIFEST.md
{
  echo "# Manifest of the frontend files"
  echo
  echo "Generated by refresh.sh. Do not edit by hand."
  echo "Rust repo: \`$(git -C "$RUST" rev-parse HEAD)\`. Reference app: \`$(git -C "$REF" rev-parse HEAD)\`."
  echo
  echo "| Path here | Source | SHA-256 |"
  echo "|---|---|---|"
  find reference vendor overrides LOAD_PATH -type f | LC_ALL=C sort | while read -r f; do
    case "$f" in
      reference/*) src="reference/${f#reference/}" ;;
      vendor/GEMS.md) src="crates/assets/vendor/MANIFEST.md" ;;
      vendor/*) src="crates/assets/${f}" ;;
      overrides/*) src="crates/assets/${f}" ;;
      LOAD_PATH) src="crates/assets/vendor/LOAD_PATH" ;;
    esac
    printf '| %s | %s | %s |\n' "$f" "$src" "$(shasum -a 256 "$f" | cut -d' ' -f1)"
  done
} > MANIFEST.md
